item.text:
{
  "translations": {
    "1": {
      "male": "Ты пришёл сюда. Ты пришёл на суд Лунных Сестёр! Мы — КОСМОС, наполняющий это место.",
      "female": "Ты пришла сюда. Ты пришла на суд Лунных Сестёр! Мы — КОСМОС, наполняющий это место."
    },
    "2": {
      "male": "Мы — ГРЁЗЫ, дарующие надежду тем, кто объят страхом.",
      "female": "Мы — ГРЁЗЫ, дарующие надежду тем, кто объят страхом."
    },
    "3": {
      "male": "И наконец, мы — ЛЮБОВЬ, способная пронзить даже самые тёмные ночи!",
      "female": "И наконец, мы — ЛЮБОВЬ, способная пронзить даже самые тёмные ночи!"
    },
    "4": {
      "male": "Ты пришёл сюда не без причины, но—странно. Ты не та душа, которую мы ожидали. Нет. Ты нечто иное.",
      "female": "Ты пришла сюда не без причины, но—странно. Ты не та душа, которую мы ожидали. Нет. Ты нечто иное."
    },
    "5": {
      "male": "Ты — Окровавленное Дитя.",
      "female": "Ты — Окровавленное Дитя."
    },
    "6": {
      "male": "На тебе печать кровавых слёз; страха. Хаоса. Почему мы видим иную душу? Ту, у которой будет иное лицо?!",
      "female": "На тебе печать кровавых слёз; страха. Хаоса. Почему мы видим иную душу? Ту, у которой будет иное лицо?!"
    },
    "7": {
      "male": "Это странно. Вы словно увидели меня настоящего, а не персонажа из этой книги.",
      "female": "Это странно. Вы словно увидели меня настоящую, а не персонажа из этой книги."
    },
    "8": {
      "male": "Это просто вздор. Я не собираюсь это слушать!",
      "female": "Это просто вздор. Я не собираюсь это слушать!"
    },
    "9": {
      "male": "Молчать! Всё это неправильно!",
      "female": "Молчать! Всё это неправильно!"
    },
    "10": {
      "male": "Но мы по-прежнему Лунные Сёстры, и наш взор проникает сквозь КОСМОС. Твой путь отмечен кровью. Этого нам достаточно, чтобы знать: твою руку надлежит остановить.",
      "female": "Но мы по-прежнему Лунные Сёстры, и наш взор проникает сквозь КОСМОС. Твой путь отмечен кровью. Этого нам достаточно, чтобы знать: твою руку надлежит остановить."
    },
    "11": {
      "male": "Сёстры! Беритесь за оружие!",
      "female": "Сёстры! Беритесь за оружие!"
    },
    "12": {
      "male": "За ГРЁЗЫ!",
      "female": "За ГРЁЗЫ!"
    },
    "13": {
      "male": "За всю ЛЮБОВЬ!",
      "female": "За всю ЛЮБОВЬ!"
    },
    "14": {
      "male": "И против тех, кто не несёт ничего, кроме смерти!",
      "female": "И против тех, кто не несёт ничего, кроме смерти!"
    }
  }
}
